import type { Prisma } from '@prisma/client';

type TransactionClient = Prisma.TransactionClient;

/**
 * Returns a concurrency-safe sequence for a project, document category and year.
 * Human-facing numbers are generated by the server; database IDs remain opaque IDs.
 */
export async function nextDocumentNumber(
  tx: TransactionClient,
  input: { projectId?: string; projectCode?: string; type: string; date?: Date; globalPrefix?: string },
): Promise<string> {
  const date = input.date ?? new Date();
  const year = date.getUTCFullYear();
  const key = `${input.projectId ?? 'GLOBAL'}:${input.type}:${year}`;
  const row = await tx.documentSequence.upsert({
    where: { key },
    create: { key, value: 1 },
    update: { value: { increment: 1 } },
    select: { value: true },
  });
  const sequence = String(row.value).padStart(input.projectId ? 4 : 6, '0');
  if (!input.projectId) return `${input.globalPrefix ?? input.type}-${year}-${sequence}`;
  const projectCode = input.projectCode;
  if (!projectCode) throw new Error('PROJECT_CODE_REQUIRED_FOR_DOCUMENT_NUMBER');
  return `${projectCode}-${input.type}-${year}-${sequence}`;
}
